import{_ as e,o as a,c as s,a6 as i}from"./chunks/framework.CtKh-5IU.js";const c=JSON.parse('{"title":"Dimplex Connex gateway","description":"Control Dimplex Connex electric heaters from MQTT and Home Assistant with an ESP32 and an nRF24L01 module. Wiring, pairing heaters to the gateway, and setting zone temperatures.","frontmatter":{"title":"Dimplex Connex gateway","description":"Control Dimplex Connex electric heaters from MQTT and Home Assistant with an ESP32 and an nRF24L01 module. Wiring, pairing heaters to the gateway, and setting zone temperatures."},"headers":[],"relativePath":"setitup/connex.md","filePath":"setitup/connex.md","lastUpdated":1795824779000}'),n={name:"setitup/connex.md"};function o(r,t,h,d,l,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="dimplex-connex-gateway-2-4-ghz" tabindex="-1">Dimplex Connex gateway (2.4 GHz) <a class="header-anchor" href="#dimplex-connex-gateway-2-4-ghz" aria-label="Permalink to &quot;Dimplex Connex gateway (2.4 GHz)&quot;">​</a></h1><p>The Connex gateway replaces or works alongside the Dimplex Connex wall controller. It talks to Connex heaters directly over their 2.4 GHz link, so each heater zone can be set from MQTT or Home Assistant.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Notes</th></tr></thead><tbody><tr><td>ESP32 dev board</td><td>Any ESP32 with the usual VSPI pins free</td></tr><tr><td>nRF24L01 or nRF24L01+ module</td><td>The PA+LNA version with an external antenna gives more range</td></tr></tbody></table><p>The Connex link runs at 250 kbps on channel 40 (2.440 GHz). There&#39;s no modification to the heaters.</p><h2 id="wiring" tabindex="-1">Wiring <a class="header-anchor" href="#wiring" aria-label="Permalink to &quot;Wiring&quot;">​</a></h2><table tabindex="0"><thead><tr><th>nRF24L01</th><th>ESP32</th><th>Build flag (default)</th></tr></thead><tbody><tr><td>GND</td><td>GND</td><td>-</td></tr><tr><td>VCC</td><td>3V3</td><td>-</td></tr><tr><td>CE</td><td>GPIO25</td><td><code>CONNEX_CE_GPIO</code> (25)</td></tr><tr><td>CSN</td><td>GPIO5</td><td><code>CONNEX_CSN_GPIO</code> (5)</td></tr><tr><td>SCK</td><td>GPIO18</td><td><code>CONNEX_SCK_GPIO</code> (18)</td></tr><tr><td>MOSI</td><td>GPIO23</td><td><code>CONNEX_MOSI_GPIO</code> (23)</td></tr><tr><td>MISO</td><td>GPIO19</td><td><code>CONNEX_MISO_GPIO</code> (19)</td></tr><tr><td>IRQ</td><td>not used</td><td>-</td></tr></tbody></table><p>Set a flag in your environment&#39;s <code>build_flags</code> to move a pin, for example <code>&#39;-DCONNEX_CE_GPIO=26&#39;</code>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>nRF24L01 modules are sensitive to supply noise. A 10 µF capacitor across VCC and GND, soldered close to the module, solves most &quot;radio not responding&quot; and range problems.</p></div><h2 id="firmware" tabindex="-1">Firmware <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;Firmware&quot;">​</a></h2><p>Build and upload the <code>esp32dev-connex</code> environment, see <a href="./../upload/builds.html">Build from source</a>. Once the gateway is online, check the radio:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoCONNEXset -m &#39;{}&#39;</code></p><p>The gateway answers on <code>home/OpenMQTTGateway/CONNEXtoMQTT/gateway</code>. Everything the gateway reports goes to this one retained topic:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;radio&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;controllerid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;learning&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;burst&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;interval&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;acks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;power&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;low&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;zones&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{}}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>If <code>radio</code> reads <code>not responding</code>, check the wiring and the capacitor.</p><h2 id="learning-an-existing-wall-controller" tabindex="-1">Learning an existing wall controller <a class="header-anchor" href="#learning-an-existing-wall-controller" aria-label="Permalink to &quot;Learning an existing wall controller&quot;">​</a></h2><p>If you have a working Connex wall controller, the gateway can share it instead of pairing the heaters again. Have the gateway learn the wall controller&#39;s ID:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoCONNEXset -m &#39;{&quot;learn&quot;:true}&#39;</code></p><p>Then change any zone on the wall controller within 2 minutes. The gateway saves the ID it hears and sends its own commands with that same ID. A heater only ever stores one controller ID, so it sees a single controller and follows both the wall controller and the gateway. From then on the gateway also reports changes made on the wall controller, with <code>&quot;source&quot;:&quot;controller&quot;</code>. You can also set an ID by hand with <code>{&quot;controllerid&quot;:&quot;A1B2&quot;,&quot;save&quot;:true}</code>.</p><p>Skip this section if you have no wall controller, or want the gateway to use its own ID: pair the heaters instead.</p><h2 id="pairing-a-heater" tabindex="-1">Pairing a heater <a class="header-anchor" href="#pairing-a-heater" aria-label="Permalink to &quot;Pairing a heater&quot;">​</a></h2><p>Each heater listens for one controller ID and one zone. Pairing gives a heater the gateway&#39;s controller ID and the zone you choose. The first pairing creates a random controller ID and saves it on the gateway.</p><ol><li><p>On the heater, hold <strong>V</strong> for 3 seconds, then press <strong>-</strong>, <strong>+</strong>, <strong>V</strong>. The heater is now waiting for a controller for about 10 seconds.</p></li><li><p>Within those 10 seconds, send the zone (1-4) and a starting temperature:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoCONNEXset -m &#39;{&quot;pair&quot;:1,&quot;temperature&quot;:20}&#39;</code></p></li><li><p>The heater display changes to the temperature you sent. If it doesn&#39;t, the 10 seconds probably ran out: repeat both steps.</p></li></ol><p>Several heaters can share a zone: pair each one to the same zone number, one at a time. Heaters already paired in that zone follow the pairing temperature too.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A heater that was paired before, to a wall controller or to another gateway, ignores a new pairing until it is unpaired. To unpair, hold <strong>V</strong> for 3 seconds, then press <strong>V</strong>, <strong>+</strong>, <strong>-</strong>. Then pair it again.</p></div><h2 id="setting-a-temperature" tabindex="-1">Setting a temperature <a class="header-anchor" href="#setting-a-temperature" aria-label="Permalink to &quot;Setting a temperature&quot;">​</a></h2><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoCONNEX -m &#39;{&quot;zone&quot;:1,&quot;temperature&quot;:20.5}&#39;</code></p><p>The temperature range is 0 to 30 °C in 0.5 °C steps, the same as the heater&#39;s own controls. Each command is sent as a burst of identical frames. The gateway then republishes its status, with the zone under <code>zones</code>:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;radio&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;controllerid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;4D06&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;learning&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;burst&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;interval&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;acks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;power&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;low&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;zones&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;setpoint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gateway&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;acked&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;age&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>If no frame is acked (heater out of range or unpowered), the zone keeps its previous <code>setpoint</code> and the attempt is reported as <code>&quot;status&quot;:&quot;failed&quot;</code> with <code>&quot;failed_setpoint&quot;</code>. A rejected command (invalid zone or temperature, no controller ID, radio not responding) publishes a non-retained status with an <code>&quot;error&quot;</code> field and sends nothing.</p><p>The protocol has no off command, and the wall controller doesn&#39;t have one either. Setting 0 °C (or 5 °C for frost protection) has the same effect.</p><p>With MQTT discovery enabled, each zone appears in Home Assistant as a climate entity, after a controller ID exists. Its setpoint is read from that zone&#39;s entry in the gateway status.</p><h2 id="what-the-gateway-can-and-can-t-know" tabindex="-1">What the gateway can and can&#39;t know <a class="header-anchor" href="#what-the-gateway-can-and-can-t-know" aria-label="Permalink to &quot;What the gateway can and can&#39;t know&quot;">​</a></h2><p>The heaters never transmit their own state. Keep this in mind when reading the gateway&#39;s messages:</p><ul><li><strong><code>acked</code></strong> counts radio-level acknowledgements. They prove a heater&#39;s radio heard the frame, not that a heater accepted it. A heater that isn&#39;t paired still acks. The heater display is the real check.</li><li><strong>Last setpoint, not current setpoint.</strong> The gateway status lists the last setpoint sent or heard per zone, with <code>age</code> in seconds since it changed. A change made on the heater&#39;s own buttons isn&#39;t visible to the gateway.</li><li><strong>After a reboot</strong> the last setpoints are restored from flash and marked <code>&quot;restored&quot;:true</code>, with <code>&quot;age&quot;:null</code> because when they changed is unknown. The gateway doesn&#39;t resend them, so it never overrides a change made on a heater while the gateway was off.</li></ul><h2 id="configuration-commands" tabindex="-1">Configuration commands <a class="header-anchor" href="#configuration-commands" aria-label="Permalink to &quot;Configuration commands&quot;">​</a></h2><p>All sent to <code>home/OpenMQTTGateway/commands/MQTTtoCONNEXset</code>:</p><table tabindex="0"><thead><tr><th>Payload</th><th>Effect</th></tr></thead><tbody><tr><td><code>{}</code></td><td>Publish the gateway status</td></tr><tr><td><code>{&quot;pair&quot;:1,&quot;temperature&quot;:20}</code></td><td>Pair a heater in sync mode to zone 1</td></tr><tr><td><code>{&quot;learn&quot;:true}</code> / <code>{&quot;learn&quot;:false}</code></td><td>Start / stop learning a wall controller&#39;s ID</td></tr><tr><td><code>{&quot;controllerid&quot;:&quot;A1B2&quot;}</code></td><td>Set the controller ID</td></tr><tr><td><code>{&quot;burst&quot;:200,&quot;interval&quot;:3,&quot;acks&quot;:10}</code></td><td>Most frames per command, milliseconds between them, and how many acks end the burst early (0 = always send them all)</td></tr><tr><td><code>{&quot;power&quot;:&quot;max&quot;}</code></td><td>Transmit power: <code>min</code>, <code>low</code>, <code>high</code> or <code>max</code> (or 0-3)</td></tr><tr><td><code>{&quot;save&quot;:true}</code></td><td>Save controller ID, burst and power settings to flash</td></tr><tr><td><code>{&quot;erase&quot;:true}</code></td><td>Erase the saved settings and last setpoints</td></tr></tbody></table><p>A single frame was enough for heaters close to the gateway. By default a command stops after 10 acked frames, and only sends up to 200 frames when acks are scarce, so a weak link gets more attempts. Acks come from whichever heater&#39;s radio answers, so with several heaters in a zone set <code>acks</code> higher, or to 0, if one of them misses commands.</p><h2 id="build-flags" tabindex="-1">Build flags <a class="header-anchor" href="#build-flags" aria-label="Permalink to &quot;Build flags&quot;">​</a></h2><p>Pin flags are in <a href="#wiring">Wiring</a>.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>CONNEX_BURST_COUNT</code></td><td>200</td><td>Frames per command</td></tr><tr><td><code>CONNEX_BURST_INTERVAL_MS</code></td><td>3</td><td>Milliseconds between frames</td></tr><tr><td><code>CONNEX_BURST_ACKS</code></td><td>10</td><td>Acked frames that end a burst early, 0 = full burst</td></tr><tr><td><code>CONNEX_PA_LEVEL</code></td><td>1 (low)</td><td>Transmit power, 0 = min to 3 = max</td></tr><tr><td><code>CONNEX_MIN_TEMP</code></td><td>0.0</td><td>Lowest accepted setpoint (°C)</td></tr><tr><td><code>CONNEX_MAX_TEMP</code></td><td>30.0</td><td>Highest accepted setpoint (°C)</td></tr></tbody></table>`,42)])])}const u=e(n,[["render",o]]);export{c as __pageData,u as default};
